if isinstance(result_str, str):
    data = json.loads(result_str)
else:
    data = result_str

experiments = data['data']['experiments']

# Find 1.7b rsft s42 dev eval (the base seed)
print("=== Looking for 1.7b rsft s42 dev eval ===")
for k, v in sorted(experiments.items()):
    kl = k.lower()
    if ('1.7b' in kl or '1_7b' in kl) and ('s42' in kl or 'seed42' in kl) and 'eval' in kl:
        metrics = v.get('metrics', {})
        if metrics.get('ign_f1'):
            print(f"  {k}: ign_f1={metrics.get('ign_f1')}")

# The plan_006 series - these seem to be the main 1.7b rsft seeds
print("\n=== plan_006 1.7b rsft evals (s42 base, s43) ===")
for k, v in sorted(experiments.items()):
    kl = k.lower()
    if 'plan_006' in kl and '1_7b' in kl and 'eval' in kl:
        metrics = v.get('metrics', {})
        print(f"  {k}: ign_f1={metrics.get('ign_f1')}, evi_f1={metrics.get('evi_f1', metrics.get('evi_f1_tp'))}")

# The plan019 series for 1.7b rsft
print("\n=== plan019 1.7b rsft evals ===")
for k, v in sorted(experiments.items()):
    kl = k.lower()
    if 'plan019' in kl and '1_7b' in kl and 'eval' in kl:
        metrics = v.get('metrics', {})
        print(f"  {k}: ign_f1={metrics.get('ign_f1')}")

# 8B SFT s42 dev eval
