for k, v in sorted(experiments.items()):
    kl = k.lower()
    if '8b' in kl and 'sft' in kl and 's42' in kl and 'eval' in kl:
        metrics = v.get('metrics', {})
        if metrics.get('ign_f1'):
            print(f"  {k}: ign_f1={metrics.get('ign_f1')}")

# 8B SFT all dev evals
print("\n=== All 8B SFT dev evals ===")
for k, v in sorted(experiments.items()):
